import test from 'node:test'
import assert from 'node:assert/strict'
import { SAMPLE } from '../src/records.js'
import { normalizeRecord } from '../src/normalize.js'

const base = SAMPLE[1]

test('normalizes SAMPLE records', () => {
  assert.deepEqual(normalizeRecord(SAMPLE[0]), {
    id: 'r2', customer: 'Ada Lovelace', amount_minor: 1250, currency: 'EUR', day: '2026-03-02',
  })
  assert.deepEqual(normalizeRecord(SAMPLE[1]), {
    id: 'r1', customer: 'Zoé Dupont', amount_minor: 300, currency: 'USD', day: '2026-03-01',
  })
})

test('customer is NFC', () => {
  assert.equal(normalizeRecord(base).customer, 'Zoé Dupont')
})

test('amount rounds half away from zero', () => {
  const a = (amount) => normalizeRecord({ ...base, amount }).amount_minor
  assert.equal(a('1.005'), 101)
  assert.equal(a('-1.005'), -101)
  assert.equal(a(0.004), 0)
  assert.equal(a('2.5'), 250)
})

test('day is UTC date', () => {
  assert.equal(normalizeRecord({ ...base, timestamp: '2026-03-02T23:30:00-05:00' }).day, '2026-03-03')
})

test('TypeError paths', () => {
  for (const amount of [NaN, Infinity, 'abc', '', null, undefined, '1.2.3']) {
    assert.throws(() => normalizeRecord({ ...base, amount }), TypeError)
  }
  for (const currency of ['EU', 'EURO', 'E1R', 'é€$', undefined, 5]) {
    assert.throws(() => normalizeRecord({ ...base, currency }), TypeError)
  }
  for (const timestamp of ['nope', '', undefined, 123]) {
    assert.throws(() => normalizeRecord({ ...base, timestamp }), TypeError)
  }
})
